import sys

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    it = iter(data)
    L = next(it)
    C = next(it)
    P = next(it)

    black = set()
    for _ in range(P):
        x = next(it)
        y = next(it)
        black.add((x - 1, y - 1))

    candidates = []
    idx = {}

    for r in range(L):
        for c in range(C):
            if (r, c) in black:
                continue

            has_black_neighbor = False
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if (nr, nc) in black:
                    has_black_neighbor = True
                    break

            if has_black_neighbor:
                idx[(r, c)] = len(candidates)
                candidates.append((r, c))

    n = len(candidates)
    adj = [[] for _ in range(n)]

    for i, (r, c) in enumerate(candidates):
        if (r + c) % 2 != 0:
            continue

        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            j = idx.get((nr, nc))
            if j is not None:
                adj[i].append(j)

    match_right = [-1] * n

    def dfs(u, seen):
        for v in adj[u]:
            if not seen[v]:
                seen[v] = True
                if match_right[v] == -1 or dfs(match_right[v], seen):
                    match_right[v] = u
                    return True
        return False

    matching = 0

    for u in range(n):
        r, c = candidates[u]
        if (r + c) % 2 == 0:
            seen = [False] * n
            if dfs(u, seen):
                matching += 1

    print(n - matching)

if __name__ == "__main__":
    main()
